def count_correct_brackets(s):
    if len(s) % 2 != 0:
        return 0  # Odd length string cannot be a valid bracket sequence

    balance = [0]  # 1st element of the array will contain 0                                            
    counter = [[0] * (len(s) + 1)]  # Main array should be filled n*n 
    balance.append(0)

    for i in range(len(s) - 1, 1, -1):
        balance.append(0)

    for i in range(len(s)):
        if s[i] == '(':
            balance[i + 1] = balance[i] + 1
        elif s[i] == ')':
            balance[i + 1] = balance[i] - 1
        if balance[i + 1] != 0:
            counter[i + 1] = counter[i]
            for j in range(1 << i):
                if j & 1:
                    counter[i + 1] += counter[i + balance[i]]
                counter[i + 1] += (j >> 1) * (j if not balance[i + 1] else 0)
                counter[i + 1] %= 1000000007
    return counter[-1]

