import math

def solve_naive(arr):
    MOD = 163577857
    count = [0] * (2*len(arr)+1)

    for i in range(len(arr)):
        for j in range(-len(arr), len(arr)+1):
            count[j+i] += 1

    return [count[i] % MOD for i in range(len(arr)*(2*len(arr)+1)//2)]

def solve_faster(arr):
    MOD = 2**64 + 1
    freq = [0] * (2*len(arr)+1)

    for i in range(len(arr)):
        for j in range(-len(arr), len(arr)+1):
            freq[(j+i) % (2*len(arr)+1)] += 1

    for i in range(1, 2*len(arr)+1):
        freq[i] += freq[i-1]

    return [freq[i] % MOD for i in range(2*len(arr)+1)]

