import math

def count_subsequences(nums, N):
    MOD = 163577857
    count = [0] * (N + 2)
    count[0] = 1

    for i in range(1, N + 2):
        for num in nums:
            if num >= 0 and i - num >= 0:
                count[i] = (count[i] + count[i - num]) % MOD
            elif num < 0 and -(i - num) <= N:
                count[i] = (count[i] + count[-i + num]) % MOD

