    while queue:
        x, y = queue.pop(0)
        for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(marked_cells[0]) and 0 <= ny < len(marked_cells) and not marked_cells[nx][ny] and not is_valid_move(x1, y1, nx, ny):
                marked_cells[nx][ny] = True
