def dfs_path_to(end_x, end_y):
    visited = {(0, 0), (end_x, end_y)}
    path = [(0, 0), (end_x, end_y)]
    x, y = end_x, end_y
    dx, dy = 1, 0
    while x != 0 or y != 0:
        nc = (x - dx + m - dx) % (2 * m - 2)
        rc = (y - dy + m - dy) % (2 * m - 2)
        if nc < rc:
            dx, dy = -dx, -dy
        else:
