import itertools

def min_moves(x1, y1, x2, y2):
    return abs(x1 - x2) + abs(y1 - y2)

def mod_pow(a, n, mod):
    result = 1
    base = a % mod
    while n > 0:
        if n & 1:
            result = (result * base) % mod
        n = n >> 1
        base = (base * base) % mod
    return result

def lattice_paths(n):
    dp = [[0 for _ in range(n+1)] for _ in range(n+1)]
    dp[0][1] = 1
    for i in range(1, n+1):
        for j in range(1, i+1):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
    return mod_pow(dp[n][n], n, 1000000007)

def lattice_shapes(n, m):
    total = 0
    paths = lattice_paths(n - 1)
    for length, n_consecutive in itertools.product(range(1, m+1), range(1, n+1)):
        if not n % length:
            continous_squares = length * n_consecutive
            additional_paths = (mod_pow(2, n_consecutive) - 1) * paths[int(continous_squares**(1/2.0)-0.5)] % 1000000007
            total = (total + additional_paths) % 1000000007
    return total

