def probability(node, graph):
    adj = {(n-1):[] for n in range(1, len(graph)+1)}
    for u, v in graph:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)
    next_state = {k:0 for k in range(len(adj))}
