            self.f.append((self.f[-1][0]*i)%MOD)
            fntab[i] = modinv(self.f[-1][0], MOD) # modinv is used to calculate factorial inversion

    def add_mod(self, x):
        self.f[0] = x
        qi = len(self.f) // 2
        top = 0
        for i in range(qi):
            vl = mul(*self.f[i:])
            tl = mul(*self.f[qi+1:], modinv(self.f[i][0], MOD))
            flip = tl + x - top
            self.f[i][0] = vl
            top = max(0, flip)
            if flip >= MOD: flip -= MOD
        while self.f: self.f =(self.f[:-1])
        return top

