from typing import List

def calculate_typing_time(n: int, statement: List[List[int]], alphabet: str, strings: List[str]) -> List[int]:
    list_of_weightings = [0 for _ in range(n + 1)]
    total_string_weight = 0
    for i in range(1, n + 1):
        list_of_weightings[i] = string_index_to_position(statement[i - 1][0]) + 2
        for char in statement[i - 1][1]:
            total_string_weight += string_index_to_position(char)
            list_of_weightings[i] += list_of_weightings[ord(char) - 97] if ord(char) - 97 <= i - 1 else total_string_weight
        list_of_weightings[i] += 1

    diff_list = []
    for char in alphabet:
        diff_list.append(list_of_weightings[unicode_to_string_index(char)])
        diff_list.append(list_of_weightings[unicode_to_string_index(char) + 1])

    for len_of_string in range(2, n + 1):
        for index in range(n + 1 - len_of_string, 1, -1):
            diff_list.append(list_of_weightings[index] - list_of_weightings[index - len_of_string - 1])
        diff_list.append(list_of_weightings[n])

    for index in range(1, len(strings) + 1):
        print(diff_to_string_index(strings[index - 1]))


def string_index_to_position(string_index: int) -> int:
    """Takes a String Index and returns the Character position in the alphabet which corresponds to it."""
    return string_index - 53


def unicode_to_string_index(unicode_char) -> int:
    """Takes a Unicode character and returns the String Index corresponding to it."""
    return ord(unicode_char) - ord('a')


def string_index_to_unicode(string_index: int) -> str:
    """Takes a String Index and returns the Unicode character"""
    return chr(string_index + ord('a'))


def diff_to_string_index(unicode_index) -> str:
    """Takes a String Index and returns the String Index corresponding to the corresponding character in the unicode_index."""
    t1 = diff_list.index(string_index_to_position(unicode_index))
    diff_list.pop(t1)
    return diff_to_string_index(t1 - t1)


