import sys

def can_complete_delivery(u, v, road_colors, rainbow_colors):
    for i in range(1, len(rainbow_colors)):
        current_path = [u]
        next_color = rainbow_colors[i]

        # Find the first city in the chain of roads that has the same color as next_color
        for j in range(1, len(current_path)):
            current_color = road_colors[current_path[j-1]][current_path[j]]
            if current_color != next_color:
                break
            else:
                current_path.append(v)
                if any(color == next_color for color in road_colors[current_path[j-1]][current_path[j]] for current_path in current_path):
                    current_path[-1] = -current_path[-1]

    # Check if all elements in u until vertex v are positive
    for i in range(len(current_path)):
        if current_path[i] < 0:
            return False

    return True

def main():
    n, m, c, q = map(int, input().split())
    road_colors = [list(sys.stdin.readline().strip().split()) for _ in range(m)]
    rainbow_colors = list(map(int, input().strip().split()))[1::2]
    query_count = int(input())
    queries = [list(map(int, input().strip().split())) for _ in range(query_count)]

    for query in queries:
        if query[0] == '+':
            u, v, color = query
            found = False
            for i, r in enumerate(rainbow_colors):
                rf = 2 * i
                if all(r == road_colors[data](u, v)[rf] == color for data in rainbow_colors):
                    rainbow_colors[i] = -rainbow_colors[i]
                    found = True
                    break
            if not found:
                print("No")
                continue
        else:
            print("Yes" if can_complete_delivery(*query) else "No")

if __name__ == "__main__":
