from collections import defaultdict
from typing import List

def encode_string(s: str) -> str:
    letter_pairs = defaultdict(str)
    for i, char in enumerate(s):
        if char in letter_pairs:
            letter_pairs[char] += (i + 1)
        else:
            letter_pairs[char] = str(i + 1)
    encoded = ''.join(letter_pairs[char] for char in s)
    return encoded

def find_positions(s: str, t: str) -> List[int]:
    s_length = len(s)
    t_length = len(t)
    t_encoded = encode_string(t)
    letter_freq = defaultdict(int)
    remaining_letters = set()

    for i in range(s_length - t_length + 1):
        current_freq = {s[i + j] for j in range(t_length)}
        if current_freq != set(t_encoded[i:i + t_length]):
            continue
        if not remaining_letters:
            remaining_letters = set(current_freq)
        else:
            intersection_letters = current_freq.intersection(remaining_letters)
            if not intersection_letters:
                remaining_letters -= current_freq

    positions = []
    for i in range(t_length - 1, s_length - t_length, -1):
        if letter_freq[next(iter(t_encoded[i]))] > next(iter(t_encoded[i])):
            positions.append(i)
            del letter_freq[next(iter(t_encoded[i]))]

    return positions

# Example usage
s = "abacabadaba"
t = "acaba"
positions = find_positions(s, t)
print(len(positions))  # Output: 3
print(" ".join(map(str, positions)))  # Output: 1 3 7
