def is_correct(s):
    balance = 0
    for bracket in s:
        if bracket == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_correct_substrings(s):
    count = 0
    for i in range(len(s)):
        if is_correct(s[:i+1]):
            count += 1
            for j in range(i+1, len(s)):
                if is_correct(s[i+1:j+1]):
                    count += 1
    return count

